package com.dy.artisan3d.utilimport android.content.Intentimport android.net.Uriimport com.dy.artisan3d.MyAppactual fun openExternalUrl(url: String) {    val intent = Intent(Intent.ACTION_VIEW, Uri.parse(url)).apply {        addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)    }    // Context-ni qayerdan olish loyihangizga bog'liq,    // odatda biror joyda static holatda saqlanadi    MyApp.context.startActivity(intent)}